void Solver::bump_var(int var, double coeff) {
    // increase activity of the variable
    double inc = var_inc * coeff;
    activity[var] += inc;

    // if a single activity becomes too large, rescale all activities to avoid overflow
    if (activity[var] > 1e90) {
        const double scale = 1e-90;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // periodic gentle decay of all activities (once every 1024 bumps) to keep the distribution fresh
    static unsigned int bump_counter = 0;
    if ((++bump_counter & 1023) == 0) { // every 1024 bumps
        const double decay = 0.95;
        for (int i = 1; i <= vars; ++i) activity[i] *= decay;
        var_inc *= decay;
    }

    // keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
